-- Generated by npm run schema:generate from src/db/schema-definition.ts.
-- Fresh database snapshot only. Upgrades use the shared versioned migrator.
-- Migration history is intentionally empty until runtime validation succeeds.

CREATE TABLE IF NOT EXISTS accounts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    alias TEXT NOT NULL,
    api_key TEXT NOT NULL UNIQUE,
    api_secret TEXT NOT NULL,
    provider TEXT NOT NULL DEFAULT 'dnshe',
    website TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS domains_cache (
    id INTEGER PRIMARY KEY,
    account_id INTEGER NOT NULL,
    subdomain TEXT NOT NULL,
    rootdomain TEXT NOT NULL,
    full_domain TEXT NOT NULL,
    status TEXT NOT NULL,
    created_at TEXT,
    expires_at TEXT NOT NULL,
    last_renewed_at TEXT,
    has_dns INTEGER DEFAULT 1,
    dns_provider TEXT,
    provider_account_id TEXT,
    remote_id TEXT,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    type TEXT NOT NULL,
    category TEXT NOT NULL,
    message TEXT NOT NULL,
    details TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS cache (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL,
    expires_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS settings (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS domain_date_overrides (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    account_id INTEGER NOT NULL,
    full_domain TEXT NOT NULL,
    registered_at TEXT,
    expires_at TEXT,
    source TEXT,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (account_id, full_domain),
    FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS custom_accounts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    group_id INTEGER NOT NULL,
    name TEXT NOT NULL,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (group_id, name),
    FOREIGN KEY (group_id) REFERENCES accounts(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS custom_domains (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    group_id INTEGER NOT NULL,
    account_id INTEGER,
    full_domain TEXT NOT NULL,
    registered_at TEXT,
    expires_at TEXT NOT NULL,
    remark TEXT,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (group_id, account_id, full_domain),
    FOREIGN KEY (group_id) REFERENCES accounts(id) ON DELETE CASCADE,
    FOREIGN KEY (account_id) REFERENCES custom_accounts(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS actions (
    id TEXT PRIMARY KEY,
    type TEXT NOT NULL,
    status TEXT NOT NULL,
    progress INTEGER NOT NULL DEFAULT 0,
    started_at TEXT,
    finished_at TEXT,
    error TEXT,
    metadata TEXT,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS audit_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    actor TEXT NOT NULL,
    action TEXT NOT NULL,
    resource_type TEXT NOT NULL,
    resource_id TEXT,
    provider TEXT,
    result TEXT NOT NULL,
    details TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS scanner_jobs (
    id TEXT PRIMARY KEY,
    status TEXT NOT NULL,
    cursor TEXT NOT NULL,
    total_checked INTEGER NOT NULL DEFAULT 0,
    available INTEGER NOT NULL DEFAULT 0,
    registered INTEGER NOT NULL DEFAULT 0,
    failed INTEGER NOT NULL DEFAULT 0,
    started_at TEXT,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    finished_at TEXT,
    error TEXT
);

CREATE TABLE IF NOT EXISTS cf_sync_state (
    account_id INTEGER PRIMARY KEY,
    generation TEXT NOT NULL,
    next_page INTEGER NOT NULL,
    total_synced INTEGER NOT NULL,
    lease_token TEXT NOT NULL,
    lease_until INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    credential_fingerprint TEXT,
    FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS cf_sync_seen (
    account_id INTEGER NOT NULL,
    generation TEXT NOT NULL,
    domain_id INTEGER NOT NULL,
    seen INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (account_id, generation, domain_id),
    FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS restore_sessions (
    id TEXT PRIMARY KEY,
    owner TEXT NOT NULL,
    manifest TEXT NOT NULL,
    key_id TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('uploading','ready','committed','cancelled')),
    next_chunk INTEGER NOT NULL DEFAULT 0,
    uploaded_rows INTEGER NOT NULL DEFAULT 0,
    uploaded_bytes INTEGER NOT NULL DEFAULT 0,
    expires_at INTEGER NOT NULL,
    fence TEXT,
    result TEXT,
    created_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS restore_chunks (
    session_id TEXT NOT NULL,
    chunk_index INTEGER NOT NULL,
    digest TEXT NOT NULL,
    normalized_digest TEXT NOT NULL,
    raw_cipher TEXT NOT NULL,
    PRIMARY KEY (session_id, chunk_index),
    FOREIGN KEY (session_id) REFERENCES restore_sessions(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS restore_rows (
    session_id TEXT NOT NULL,
    table_name TEXT NOT NULL,
    row_index INTEGER NOT NULL,
    row_id INTEGER NOT NULL,
    identity TEXT NOT NULL,
    remote_identity TEXT,
    payload TEXT NOT NULL,
    PRIMARY KEY (session_id, table_name, row_index),
    UNIQUE (session_id, table_name, row_id),
    UNIQUE (session_id, table_name, identity),
    UNIQUE (session_id, table_name, remote_identity),
    FOREIGN KEY (session_id) REFERENCES restore_sessions(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS sync_work (
    id TEXT PRIMARY KEY,
    action_id TEXT NOT NULL,
    account_id INTEGER NOT NULL,
    alias TEXT NOT NULL,
    fingerprint TEXT NOT NULL,
    renew INTEGER NOT NULL DEFAULT 0,
    scheduled INTEGER NOT NULL DEFAULT 0,
    status TEXT NOT NULL CHECK (status IN ('queued','running','paused','completed','failed','cancelled')),
    cursor TEXT NOT NULL DEFAULT '{}',
    failures INTEGER NOT NULL DEFAULT 0,
    lease_token TEXT,
    lease_until INTEGER NOT NULL DEFAULT 0,
    not_before INTEGER NOT NULL DEFAULT 0,
    deadline_at INTEGER NOT NULL,
    error TEXT,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    FOREIGN KEY (action_id) REFERENCES actions(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS sync_rows (
    job_id TEXT NOT NULL,
    domain_id INTEGER NOT NULL,
    payload TEXT NOT NULL,
    enriched INTEGER NOT NULL DEFAULT 0,
    dns_attempts INTEGER NOT NULL DEFAULT 0,
    error TEXT,
    renew_state TEXT NOT NULL DEFAULT 'none',
    PRIMARY KEY (job_id, domain_id),
    FOREIGN KEY (job_id) REFERENCES sync_work(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS sync_candidates (
    job_id TEXT NOT NULL,
    domain_id INTEGER NOT NULL,
    PRIMARY KEY (job_id, domain_id),
    FOREIGN KEY (job_id) REFERENCES sync_work(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS sync_renew_journal (
    account_id INTEGER NOT NULL,
    domain_id INTEGER NOT NULL,
    full_domain TEXT NOT NULL,
    original_expiry TEXT NOT NULL,
    status TEXT NOT NULL,
    updated_at INTEGER NOT NULL,
    new_expiry TEXT,
    request_token TEXT,
    PRIMARY KEY (account_id, domain_id, full_domain, original_expiry)
);

CREATE TABLE IF NOT EXISTS notification_outbox (
    id TEXT PRIMARY KEY,
    event_key TEXT NOT NULL,
    channel TEXT NOT NULL,
    target_id TEXT NOT NULL,
    payload_cipher TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('queued','running','sent','dead','cancelled')),
    attempts INTEGER NOT NULL DEFAULT 0,
    uncertain INTEGER NOT NULL DEFAULT 0,
    lease_token TEXT,
    lease_until INTEGER NOT NULL DEFAULT 0,
    not_before INTEGER NOT NULL,
    deadline_at INTEGER NOT NULL,
    last_error TEXT,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    sent_at INTEGER
);

CREATE TABLE IF NOT EXISTS notification_scans (
    id TEXT PRIMARY KEY,
    scan_day TEXT NOT NULL,
    target_set TEXT NOT NULL,
    last_kind TEXT NOT NULL DEFAULT '',
    last_id INTEGER NOT NULL DEFAULT 0,
    completed INTEGER NOT NULL DEFAULT 0,
    lease_token TEXT NOT NULL,
    lease_until INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
);

